const crypto = require('crypto');
const errData = $input.first().json;

const workflowName = errData.workflow?.name || 'Unknown LendLoop Workflow';
const executionId = errData.execution?.id || String(Date.now());
const errorMessage = errData.execution?.error?.message || 'Unhandled n8n workflow execution failure';
const lastNodeExecuted = errData.execution?.lastNodeExecuted || 'UnknownNode';

// Never fail silently: emit structured operator alert log
console.error(JSON.stringify({
  level: 'ERROR',
  channel: 'lendloop_error_workflow',
  alertRecipient: $env.OPS_ALERT_EMAIL || 'ops@lendloop.local',
  workflowName,
  executionId,
  lastNodeExecuted,
  errorMessage,
  occurredAt: new Date().toISOString()
}));

const callbackPayload = {
  idempotencyKey: `n8n-error:${executionId}`,
  workflow: 'error_handler',
  eventType: 'workflow.error',
  status: 'failed',
  summary: `n8n failure in ${workflowName} (${lastNodeExecuted})`,
  attemptCount: 1,
  errorMessage: errorMessage.slice(0, 300)
};

const rawCallbackBody = JSON.stringify(callbackPayload);
const ts = String(Math.floor(Date.now() / 1000));
const sig = 'sha256=' + crypto
  .createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET)
  .update(`${ts}.${rawCallbackBody}`)
  .digest('hex');

return [{
  json: {
    callbackUrl: `${$env.CONVEX_SITE_URL}/api/n8n/automation-events`,
    rawCallbackBody,
    ts,
    sig,
    idempotencyKey: callbackPayload.idempotencyKey
  }
}];
